using Ecom.Domain.Entities;

namespace Ecom.Application.Features.Commerce.System.Queries.GetManagementAuditLogs;
public sealed record GetManagementAuditLogsQuery : IRequest<TResult<PaginatedList<AuditLogDto>>>
{ public Guid? ActorUserId{get;init;} public string? EntityName{get;init;} public Guid? EntityId{get;init;} public DateTime? FromUtc{get;init;} public DateTime? ToUtc{get;init;} public int Page{get;init;}=1; public int PageSize{get;init;}=50; public int Skip()=> (Page-1)*PageSize; }
public sealed class GetManagementAuditLogsQueryValidator:AbstractValidator<GetManagementAuditLogsQuery>{public GetManagementAuditLogsQueryValidator(){RuleFor(x=>x.Page).GreaterThan(0);RuleFor(x=>x.PageSize).InclusiveBetween(1,100);RuleFor(x=>x).Must(x=>!x.FromUtc.HasValue||!x.ToUtc.HasValue||x.FromUtc<=x.ToUtc).WithMessage("FromUtc must be earlier than or equal to ToUtc.");}}
public sealed class GetManagementAuditLogsQueryHandler(IUnitOfWork uow,ICurrentUser currentUser):IRequestHandler<GetManagementAuditLogsQuery,TResult<PaginatedList<AuditLogDto>>>
{public async Task<TResult<PaginatedList<AuditLogDto>>> Handle(GetManagementAuditLogsQuery r,CancellationToken ct){if(!currentUser.IsAuthenticated)return TResult<PaginatedList<AuditLogDto>>.Failure(MessageKey.Unauthorized,ErrorCodes.UNAUTHORIZED);if(!currentUser.HasPolicy(Permissions.Audit.Read))return TResult<PaginatedList<AuditLogDto>>.Failure(MessageKey.Forbidden,ErrorCodes.FORBIDDEN);var q=uow.Repository<AuditLog>().QueryNoTracking();if(r.ActorUserId.HasValue)q=q.Where(x=>x.ActorUserId==r.ActorUserId);if(!string.IsNullOrWhiteSpace(r.EntityName))q=q.Where(x=>x.EntityName==r.EntityName.Trim());if(r.EntityId.HasValue)q=q.Where(x=>x.EntityId==r.EntityId);if(r.FromUtc.HasValue)q=q.Where(x=>x.OccurredAt>=r.FromUtc);if(r.ToUtc.HasValue)q=q.Where(x=>x.OccurredAt<=r.ToUtc);var total=await q.CountAsync(ct);var rows=await q.OrderByDescending(x=>x.OccurredAt).Skip(r.Skip()).Take(r.PageSize).Select(x=>new AuditLogDto(x.Id,x.ActorUserId,x.Action,x.EntityName,x.EntityId,x.CorrelationId,x.OccurredAt)).ToListAsync(ct);return TResult<PaginatedList<AuditLogDto>>.Success(PaginatedList<AuditLogDto>.Create(rows,total,r.Page,r.PageSize));}}
